// Textos del panel /admin, uno por idioma. Tono impersonal en todos.
// Lo carga index.html antes de su script; las const quedan como globales.
"use strict";
// Plural ucraniano: 1 пісня, 2-4 пісні, 5+ пісень (11-14 siempre el tercero)
const plUk = (n, one, few, many) => {
  const d = n % 10, h = n % 100;
  return `${n} ${d === 1 && h !== 11 ? one : d >= 2 && d <= 4 && (h < 12 || h > 14) ? few : many}`;
};
